def number_existing_sheets(apps, schema_editor):
    """Give every sheet that already exists its intake number: 001 for the
    oldest, then up in the order they were started. Each number goes in the
    register as IN_USE - none of them is ever free to use again unless a
    manager later deletes that sheet while it is empty."""
    IntakeSheet = apps.get_model("warehouse", "IntakeSheet")
    IntakeNumber = apps.get_model("warehouse", "IntakeNumber")
    sheets = IntakeSheet.objects.filter(number__isnull=True).order_by("created_at", "pk")
    for number, sheet in enumerate(sheets.iterator(), start=1):
        IntakeSheet.objects.filter(pk=sheet.pk).update(number=number)
        IntakeNumber.objects.create(number=number, state="in_use", sheet_id=sheet.pk)


